const response = $input.first().json;

const accessToken =
  response?.access_token ??
  response?.data?.access_token ??
  response?.result?.access_token ??
  response?.token?.access_token ??
  response?.data?.token;

if (!accessToken || !String(accessToken).trim()) {
  const safeKeys = Object.keys(response ?? {});
  throw new Error(
    `Access token tidak ditemukan pada respons Olsera. Field tingkat atas: ${safeKeys.join(', ') || '(kosong)'}.`
  );
}

return [{
  json: {
    access_token: String(accessToken).trim(),
    refresh_token:
      response?.refresh_token ??
      response?.data?.refresh_token ??
      response?.result?.refresh_token ??
      null,
    expires_in:
      response?.expires_in ??
      response?.data?.expires_in ??
      response?.result?.expires_in ??
      null,
  },
}];

const response = $input.first().json;
const syncStartedAt = new Date().toISOString();

const candidates = [
  response,
  response?.data,
  response?.products,
  response?.items,
  response?.data?.data,
  response?.data?.products,
  response?.data?.items,
];

const items = candidates.find((value) => Array.isArray(value));

if (!items) {
  throw new Error(
    'Format respons Olsera belum dikenali. Periksa output node "Ambil Data Produk Olsera" lalu sesuaikan daftar candidates pada Code node.'
  );
}

if (items.length === 0) {
  throw new Error(
    'Olsera mengembalikan 0 produk. Sinkronisasi dihentikan agar data kosong tidak dianggap sebagai hasil yang valid.'
  );
}

const firstDefined = (...values) =>
  values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');

const toText = (...values) => {
  const value = firstDefined(...values);
  return value === undefined ? '' : String(value).trim();
};

const toNumber = (value, fallback = 0) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'number') return Number.isFinite(value) ? value : fallback;

  const raw = String(value).trim().replace(/\s/g, '');
  if (!raw) return fallback;

  const commaIndex = raw.lastIndexOf(',');
  const dotIndex = raw.lastIndexOf('.');
  const normalized = commaIndex > dotIndex
    ? raw.replace(/\./g, '').replace(',', '.')
    : raw.replace(/,/g, '');

  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const toBoolean = (value, fallback = true) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;

  const normalized = String(value).trim().toLowerCase();
  if (['false', '0', 'no', 'tidak', 'inactive', 'nonaktif'].includes(normalized)) return false;
  if (['true', '1', 'yes', 'ya', 'active', 'aktif'].includes(normalized)) return true;
  return fallback;
};

const toIsoDateOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
};

return items.map((product, index) => {
  const olseraId = toText(product.id, product.product_id, product.productId);
  const name = toText(product.name, product.title, product.product_name);

  if (!olseraId || !name) {
    throw new Error(
      `Produk Olsera pada index ${index} tidak valid: id="${olseraId}", name="${name}".`
    );
  }

  const sku = toText(product.sku, product.barcode, product.code);
  const price = toNumber(firstDefined(product.sell_price, product.price, product.variant_price), 0);
  const buyPrice = toNumber(firstDefined(product.buy_price, product.cost_price), 0);
  const stock = Math.trunc(
    toNumber(firstDefined(product.stock, product.total_stock, product.qty, product.quantity), 0)
  );
  const weight = toNumber(firstDefined(product.weight, product.weight_gram), 0);
  const description = toText(product.description, product.note);
  const category = toText(product.category_name, product.category, 'Umum');
  const brand = toText(product.brand_name, product.brand, 'Grandivo');
  const imageUrl = toText(
    product.photo,
    product.image_url,
    product.picture,
    product.image,
    product.images?.[0]?.url,
    product.images?.[0]
  );
  const isActive = toBoolean(
    firstDefined(product.is_active, product.active, product.status),
    true
  );
  const sourceUpdatedAt = toIsoDateOrNull(
    firstDefined(product.updated_at, product.modified_at, product.last_update)
  );

  return {
    json: {
      olsera_id: olseraId,
      name,
      sku,
      price,
      buy_price: buyPrice,
      stock,
      weight,
      description,
      category,
      brand,
      image_url: imageUrl,
      is_active: isActive,
      source_updated_at: sourceUpdatedAt,
      raw_payload: JSON.stringify(product),
      sync_started_at: syncStartedAt,
    },
  };
});

const rows = $input.all();
const totalSynced = rows.length;
const timestamp = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });

if (totalSynced === 0) {
  throw new Error('Tidak ada produk yang berhasil di-upsert ke PostgreSQL.');
}

return [{
  json: {
    status: 'SUCCESS',
    message: `Berhasil sinkronisasi ${totalSynced} produk dari Olsera ke PostgreSQL.`,
    total_synced: totalSynced,
    synced_at_wib: timestamp,
  },
}];
